-- v94 thumbnail source failover schema
create table if not exists public.crowspace_thumbnail_source_candidates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, media_id uuid not null references public.crowspace_hero_media(id) on delete cascade, source_url text not null, source_type text not null default 'alternate', priority integer not null default 100, is_primary boolean not null default false, health_score numeric(5,2) not null default 50, success_count integer not null default 0, failure_count integer not null default 0, consecutive_failures integer not null default 0, last_success_at timestamptz, last_failure_at timestamptz, last_status integer, enabled boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(media_id,source_url));
alter table public.crowspace_thumbnail_source_candidates enable row level security;
create index if not exists idx_thumbnail_source_candidates_media on public.crowspace_thumbnail_source_candidates(media_id,health_score desc,priority asc);
alter table public.crowspace_hero_media add column if not exists thumbnail_primary_source_id uuid references public.crowspace_thumbnail_source_candidates(id) on delete set null;